parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "companies": {
      "type": "array",
      "items": {
        "type": "object",
        "properties": {
          "name": {
            "type": "string"
          },
          "cash": {
            "type": "string",
            "description": "As returned, with currency, e.g. \"$626,480\"; \"unknown\" if null"
          },
          "net_burn_monthly": {
            "type": "string",
            "description": "As returned per month, with currency; \"unknown\" if null"
          },
          "runway_months": {
            "type": [
              "number",
              "null"
            ],
            "description": "As returned; null when unknown or not burning"
          },
          "runway_note": {
            "type": "string",
            "description": "Empty, or why runway has no number: \"not burning\" or the unknown_reason"
          },
          "top_moves": {
            "type": "array",
            "items": {
              "type": "object",
              "properties": {
                "counterparty": {
                  "type": "string"
                },
                "amount": {
                  "type": "string",
                  "description": "Signed exactly as returned: -$ is money out, +$ is money in"
                }
              },
              "required": [
                "counterparty",
                "amount"
              ]
            }
          }
        },
        "required": [
          "name",
          "cash",
          "net_burn_monthly",
          "runway_months",
          "runway_note",
          "top_moves"
        ]
      }
    }
  },
  "required": [
    "companies"
  ]
}

parameters.jsCode:
// Turns the agent's JSON into the Slack digest, plus an alert for companies under the runway threshold.
const s = $('Settings').first().json;
const companies = $json.output?.companies ?? [];
// Review items come straight from list_review_items (not from the AI), counted per company.
const reviewText = ($('Get review items').first().json.content ?? []).map((c) => (typeof c.text === 'string' ? c.text : JSON.stringify(c.text))).join('\n');
const reviewJson = reviewText.indexOf('{"items"') >= 0 ? JSON.parse(reviewText.slice(reviewText.indexOf('{"items"'))) : { items: [] };
const reviews = {};
for (const it of reviewJson.items ?? []) reviews[it.company] = (reviews[it.company] ?? 0) + 1;
// Upcoming items also come straight from list_upcoming (next 14 days).
const upText = ($('Get upcoming').first().json.content ?? []).map((c) => (typeof c.text === 'string' ? c.text : JSON.stringify(c.text))).join('\n');
const upcoming = upText.indexOf('{"days"') >= 0 ? JSON.parse(upText.slice(upText.indexOf('{"days"'))).items ?? [] : [];
const money = (m) => {
  const n = Number(m.amount);
  const v = Math.abs(n).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  return `${n < 0 ? '-' : '+'}${m.currency === 'USD' ? '$' + v : v + ' ' + m.currency}`;
};
const lines = [];
for (const c of companies) {
  const runway = c.runway_months == null ? (c.runway_note || 'unknown') : `${c.runway_months} months`;
  // A negative net burn means cash grew; say so instead of printing a minus burn.
  const burn = /^-/.test(c.net_burn_monthly) ? `cash growing ${c.net_burn_monthly.slice(1)}/mo` : /\d/.test(c.net_burn_monthly) ? `net burn ${c.net_burn_monthly}/mo` : 'net burn unknown';
  lines.push(`*${c.name}*: cash ${c.cash} · ${burn} · runway ${runway}`);
  const moves = (c.top_moves || []).filter((m) => !/^[+-]?\D*0(\.0+)?$/.test(m.amount.replace(/,/g, '')));
  for (const m of moves.slice(0, 3)) {
    const who = !m.counterparty || /^(none|unknown|null)$/i.test(m.counterparty) ? 'No payee name' : m.counterparty;
    lines.push(`  • ${who}: ${m.amount}`);
  }
  const due = upcoming.filter((u) => u.company === c.name && Math.abs(Number(u.amount.amount)) >= s.dueAlertAmount).map((u) => `${u.what} ${money(u.amount)} (${u.date}${u.confidence === 'estimated' ? ', estimated' : ''})`);
  if (due.length) lines.push(`  Due in the next 14 days: ${due.join('; ')}`);
  const r = reviews[c.name] ?? 0;
  if (r > 0) lines.push(`  ${r} item${r === 1 ? '' : 's'} to review in Aggregate`);
}
const low = companies.filter((c) => typeof c.runway_months === 'number' && c.runway_months < s.runwayAlertMonths);
const digest = companies.length ? `*Weekly cash and runway*\n${lines.join('\n')}` : '*Weekly cash and runway*\nAggregate returned no companies for this connection.';
const alert = low.length
  ? `<!here> Runway under ${s.runwayAlertMonths} months: ${low.map((c) => `*${c.name}* ${c.runway_months} months (cash ${c.cash}, burn ${c.net_burn_monthly}/mo)`).join('; ')}`
  : '';
return [{ json: { digest, alert, alertCount: low.length } }];
